     * `ModuleRegistry.registerModules([ValidationModule.with({ throwOn: ['error'] })])`.
     * Configuration is global (see {@link DevValidationOptions}) — passing different options per
     * grid does not scope them per grid; the last call wins for all grids.
     */
    var with: (DevValidationOptions) -> _ModuleWithoutApi
}

/**
 * All the AG Grid components that are used within internal templates via <ag-autocomplete> syntax
 * @internal AG_GRID_INTERNAL - Not for public use. Can change / be removed at any time.
 */
external interface AgComponentSelectorType

inline fun AgComponentSelectorType(value: AgWidgetSelectorType): AgComponentSelectorType = value.unsafeCast<AgComponentSelectorType>()
inline fun AgComponentSelectorType(value: String): AgComponentSelectorType = value.unsafeCast<AgComponentSelectorType>()

/**
 * @internal AG_GRID_INTERNAL - Not for public use. Can change / be removed at any time.
 */
typealias ComponentSelector = JsAny

/**
 * 上游字符串字面量联合：`tap`、`doubleTap`、`longTap`。
 */
sealed external interface TouchListenerEvent

inline fun TouchListenerEvent(value: String): TouchListenerEvent = value.unsafeCast<TouchListenerEvent>()

object TouchListenerEvents {
    inline val tap: TouchListenerEvent get() = TouchListenerEvent("tap")
    inline val doubleTap: TouchListenerEvent get() = TouchListenerEvent("doubleTap")
    inline val longTap: TouchListenerEvent get() = TouchListenerEvent("longTap")
}

typealias AnyString = JsAny

external interface CreatePartArgs {
    /**
     * A string feature, e.g. 'iconSet'. Adding a part to a theme will remove any existing part with
     * the same feature.
     */
    var feature: JsAny?
    /**
     * Default parameters for the part.
     */
    var params: WithParamTypes?
    /**
     * Parameters for different theme modes, e.g. 'dark' or 'light'. Setting `modeParams: {myMode:
     * {myColor: 'red'}}` on a theme part is the equivalent of `theme.withParams({myColor: 'red'},
     * 'myMode')`.
     */
    var modeParams: Record<String, WithParamTypes>?
    /**
     * CSS styles associated with this part. The CSS will be injected into the page when the theme
     * is used by a grid. The grid uses CSS nested to wrap this CSS in a selector that ensures it
     * only applies to grids that are using a theme containing this part.
     */
    var css: StringOrString?
    /**
     * URLs of CSS files to import before the part's CSS.
     */
    var cssImports: Array<String>?
}

typealias ExpandTypeKeys = JsAny
